using Microsoft.EntityFrameworkCore;using TechnifyERP.Application.Website;using TechnifyERP.Domain.Entities;using TechnifyERP.Infrastructure.Persistence;
namespace TechnifyERP.Infrastructure.Website;
internal sealed class HomepageService(ApplicationDbContext db):IHomepageService{public async Task<HomepageContentDto>GetAsync(CancellationToken ct=default){var x=await db.HomepageContents.AsNoTracking().FirstOrDefaultAsync(ct);var stats=await db.HomepageStats.AsNoTracking().OrderBy(x=>x.DisplayOrder).Select(x=>new HomepageStatDto(x.Label,x.Value,x.DisplayOrder)).ToListAsync(ct);var features=await db.HomepageFeatures.AsNoTracking().OrderBy(x=>x.DisplayOrder).Select(x=>new HomepageFeatureDto(x.Title,x.Description,x.DisplayOrder)).ToListAsync(ct);return x is null?new("Learn. Build. Achieve.","A modern learning platform for students and faculty.","Get Started","/Identity/Account/Register","Empowering learners for the future.",stats,features):new(x.HeroTitle,x.HeroSubtitle,x.PrimaryButtonText,x.PrimaryButtonUrl,x.FooterText,stats,features);}public async Task SaveAsync(HomepageContentDto x,CancellationToken ct=default){var e=await db.HomepageContents.FirstOrDefaultAsync(ct);if(e is null){db.Add(new HomepageContent{HeroTitle=x.HeroTitle,HeroSubtitle=x.HeroSubtitle,PrimaryButtonText=x.PrimaryButtonText,PrimaryButtonUrl=x.PrimaryButtonUrl,FooterText=x.FooterText});}else{e.HeroTitle=x.HeroTitle;e.HeroSubtitle=x.HeroSubtitle;e.PrimaryButtonText=x.PrimaryButtonText;e.PrimaryButtonUrl=x.PrimaryButtonUrl;e.FooterText=x.FooterText;e.UpdatedAtUtc=DateTime.UtcNow;}await db.SaveChangesAsync(ct);}public async Task SaveSectionsAsync(IReadOnlyList<HomepageStatDto> stats,IReadOnlyList<HomepageFeatureDto> features,CancellationToken ct=default){db.HomepageStats.RemoveRange(db.HomepageStats);db.HomepageFeatures.RemoveRange(db.HomepageFeatures);db.HomepageStats.AddRange(stats.Where(x=>!string.IsNullOrWhiteSpace(x.Label)&&!string.IsNullOrWhiteSpace(x.Value)).Select(x=>new HomepageStat{Label=x.Label.Trim(),Value=x.Value.Trim(),DisplayOrder=x.DisplayOrder}));db.HomepageFeatures.AddRange(features.Where(x=>!string.IsNullOrWhiteSpace(x.Title)&&!string.IsNullOrWhiteSpace(x.Description)).Select(x=>new HomepageFeature{Title=x.Title.Trim(),Description=x.Description.Trim(),DisplayOrder=x.DisplayOrder}));await db.SaveChangesAsync(ct);}}
